import numpy as np

def lr_schedule(t, warmup=100, total=1000, max_lr=1e-3):
    if t < warmup:
        return max_lr * t / warmup
    progress = (t - warmup) / (total - warmup)
    return max_lr * 0.5 * (1 + np.cos(np.pi * progress))
